```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def fit(self, X, y):
        # Simple linear regression using least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def fit(self, X, y):
        pass

    def predict(self, X):
        return np.random.rand(len(X))

class DecisionTreeModel(Model):
    def fit(self, X, y):
        # Placeholder for decision tree fitting logic
        pass

    def predict(self, X):
        # Placeholder for decision tree prediction logic
        return np.random.rand(len(X))

class ContextualMultiArmedBandit:
    def __init__(self, context_dim, num_arms=3, models=None):
        if models is None:
            models = [LinearModel(), RandomModel(), DecisionTreeModel()]

        self.context_dim = context_dim
        self.num_arms = num_arms
        self.models = models
        self.rewards = np.zeros(num_arms)
        self.counts = np.zeros(num_arms)

    def select_arm(self, context):
        # Select the arm with the highest predicted reward
        predictions = [model.predict(context.reshape(1, -1)) for model in self.models]
        selected_arm = np.argmax(predictions[0])
        return selected_arm

    def update(self, arm, reward):
        self.rewards[arm] += reward
        self.counts[arm] += 1

    def get_average_reward(self, arm):
        if self.counts[arm] == 0:
            return 0
        return self.rewards[arm] / self.counts[arm]

# Example usage
if __name__ == "__main__":
    context_dim = 2
    num_arms = 3
    bandit = ContextualMultiArmedBandit(context_dim, num_arms)

    contexts = np.random.rand(100, context_dim)
    true_rewards = np.random.rand(100, num_arms)

    for i in range(100):
        context = contexts[i]
        arm = bandit.select_arm(context)
        reward = true_rewards[i][arm]
        bandit.update(arm, reward)

    print("Average rewards per arm:", [bandit.get_average_reward(i) for i in range(num_arms)])
```

### Explanation:

1. **Models**:
   - `LinearModel`: A simple linear regression model.
   - `RandomModel`: A random model that generates random predictions.
   - `DecisionTreeModel`: A placeholder for a decision tree model.

2. **ContextualMultiArmedBandit**:
   - Initializes with a given context dimension and number of arms.
   - Uses the provided models or defaults to the three models defined above.
   - The `select_arm` method selects the arm with the highest predicted reward based on the current context.
   - The `update` method updates the average reward for the selected arm.
   - The `get_average_reward` method returns the average reward for a specific arm.

3. **Example Usage**:
   - Generates some synthetic data for contexts and true rewards.
   - Runs the bandit algorithm over 100 iterations, updating the bandit's state after each iteration.
   - Prints the average reward for each arm at the end.

This script provides a basic framework for implementing a contextual multi-armed bandit problem with multiple models. You can extend it by adding more sophisticated models or modifying the selection strategy.

