```javascript
document.addEventListener('DOMContentLoaded', function() {
  const handle = document.querySelector('.handle');
  const circleContainer = document.querySelector('.circle-container');

  let isDragging = false;

  handle.addEventListener('mousedown', () => {
    isDragging = true;
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;

    const rect = circleContainer.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;

    const angle = Math.atan2(e.clientY - centerY, e.clientX - centerX);
    const distanceFromCenter = Math.sqrt(Math.pow(e.clientX - centerX, 2) + Math.pow(e.clientY - centerY, 2));

    // Ensure the handle stays within the circle bounds
    const maxDistance = rect.width / 2;
    const clampedDistance = Math.min(distanceFromCenter, maxDistance);

    const newX = centerX + clampedDistance * Math.cos(angle);
    const newY = centerY + clampedDistance * Math.sin(angle);

    handle.style.transform = `translate(${newX}px, ${newY}px)`;
  });
});
```

