     * Add a name to the favorites list.
     *
     * @param Request $request The incoming request.
     * @return \Illuminate\Http\JsonResponse A JSON response indicating success or failure.
     */
    public function addFavorite(Request $request)
    {
        $name = $request->input('name');

        try {
            $this->favoritesManager->addToFavorites($name);
            return response()->json(['message' => 'Name added to favorites successfully.'], 200);
        } catch (\Exception $e) {
            return response()->json(['error' => 'Failed to add name to favorites.', 'details' => $e->getMessage()], 500);
