2. Define the `Data` struct as you have done:
```cpp
struct Data {
    double v[3];
    int n;
};
```
3. Create a function to define the compound data type:
```cpp
HighFive::CompType<Data> createCompoundDataType() {
    // Create a new compound data type with 4 fields (3 doubles + 1 integer)
    auto compType = HighFive::CompType<Data>(4);

    // Add the 'v' field (an array of 3 doubles) at offset 0
    compType.insertMember("v", 0, HighFive::ArrayType<double, 3>());

    // Add the 'n' field (an integer) at offset 12 (3 * sizeof(double))
    compType.insertMember("n", 12, HighFive::IntType());

    return compType;
}
```
4. Now, you can use this compound data type to write and read your `Data` structs to/from an HDF5 file:
```cpp
void writeToHDF5(const std::string& filename, const std::vector<Data>& data) {
    // Open or create the HDF5 file
    HighFive::File file(filename, HighFive::File::ReadWrite | HighFive::File::Create | HighFive::File::Truncate);

    // Get the compound data type
    auto dataType = createCompoundDataType();

    // Create a dataset with the compound data type
    auto dataset = file.createDataSet<Data>("data", dataType);

    // Write the data to the dataset
    dataset.write(data);
}

std::vector<Data> readFromHDF5(const std::string& filename) {
    // Open the HDF5 file
    HighFive::File file(filename, HighFive::File::ReadOnly);

    // Get the compound data type
    auto dataType = createCompoundDataType();

    // Read the data from the dataset
    std::vector<Data> data;
    file.getDataSet("data").read(data, dataType);

    return data;
}
```
