To create a flexible and extensible `Action` class that can handle various types of interactions between characters, we'll need to define a way to configure these actions through external files or dictionaries. This allows us to easily add new actions without modifying the core logic of the `Action` class.

Here’s a basic implementation in Python:

```python
import json

class Action:
    def __init__(self, action_config):
        self.action_type = action_config.get("type")
        self.target = None
        self.actor = None
        self.config = action_config

    def execute(self, actor, target=None):
        if self.action_type == "deal_damage":
            return self._deal_damage(actor, target)
        elif self.action_type == "heal_actor":
            return self._heal_actor(actor)
        elif self.action_type == "heal_target":
            return self._heal_target(actor, target)
        elif self.action_type == "deal_damage_portion_health":
            return self._deal_damage_portion_health(actor, target)
        elif self.action_type == "deal_damage_life_leech":
            return self._deal_damage_life_leech(actor, target)
        else:
            raise ValueError(f"Unknown action type: {self.action_type}")

    def _deal_damage(self, actor, target):
        amount = self.config.get("amount", actor.damage)
        target.hp -= amount
        print(f"{actor.name} deals {amount} damage to {target.name}. {target.name}'s HP is now {target.hp}")
        return {"action": "deal_damage", "actor": actor.name, "target": target.name, "amount": amount}

    def _heal_actor(self, actor):
        amount = self.config.get("amount", 10)  # Default healing amount
        actor.hp += amount
        print(f"{actor.name} heals itself for {amount}. {actor.name}'s HP is now {actor.hp}")
        return {"action": "heal_actor", "actor": actor.name, "amount": amount}

    def _heal_target(self, actor, target):
        amount = self.config.get("amount", 10)  # Default healing amount
        target.hp += amount
        print(f"{actor.name} heals {target.name} for {amount}. {target.name}'s HP is now {target.hp}")
        return {"action": "heal_target", "actor": actor.name, "target": target.name, "amount": amount}

    def _deal_damage_portion_health(self, actor, target):
        portion = self.config.get("portion", 0.1)  # Default portion of target's health
        amount = int(target.hp * portion)
        target.hp -= amount
        print(f"{actor.name} deals {amount} damage to {target.name} based on its health. {target.name}'s HP is now {target.hp}")
        return {"action": "deal_damage_portion_health", "actor": actor.name, "target": target.name, "amount": amount}

    def _deal_damage_life_leech(self, actor, target):
        portion = self.config.get("portion", 0.1)  # Default portion of dealt damage
        amount = int(target.hp * portion)
        target.hp -= amount
        actor.hp += amount
        print(f"{actor.name} deals {amount} damage to {target.name} and heals itself for {amount}. {actor.name}'s HP is now {actor.hp}, {target.name}'s HP is now {target.hp}")
        return {"action": "deal_damage_life_leech", "actor": actor.name, "target": target.name, "amount": amount}
